// Package jsonschema ships the published JSON Schemas of the FORA wire messages.
//
// The directory holds one self-contained draft 2020-12 schema per message of the wire
// contract, named by the fully-qualified message name, in two variants:
//
//	fora.v1.ResourceResponse.schema.json         unknown fields accepted
//	fora.v1.ResourceResponse.schema.strict.json  unknown fields refused at every depth
//
// The schema files are generated by scripts/gen-sdk-types.sh and checked against the
// proto by the drift gate; this file is hand-written. FS embeds them, so a Go program
// reads the schemas of the module version it pins without locating the module cache.
// README.md in this directory records the wire decisions the schemas encode.
package jsonschema

import (
	"embed"
	"fmt"
	"io/fs"
)

// FS holds every published schema file, at the root of the file system.
//
//go:embed *.json
var FS embed.FS

// Load returns the schema of the message name, for example "fora.v1.ResourceResponse".
// strict selects the variant that refuses unknown fields. An unknown name is an error
// that wraps fs.ErrNotExist.
func Load(name string, strict bool) ([]byte, error) {
	file := name + ".schema.json"
	if strict {
		file = name + ".schema.strict.json"
	}
	if !fs.ValidPath(file) {
		return nil, fmt.Errorf("jsonschema: invalid message name %q: %w", name, fs.ErrNotExist)
	}
	b, err := FS.ReadFile(file)
	if err != nil {
		return nil, fmt.Errorf("jsonschema: no published schema for message %q: %w", name, err)
	}
	return b, nil
}
